properties.query:
let baselineWindow = 24h;
let lookbackWindow = 5m;
let alertWindow = 15m;
let zScoreThreshold = 3.0;
let minAttempts = 5;
let successRateGate = 0.99;
let PerBin =
    UAVOpAudit_CL
    | where TimeGenerated > ago(baselineWindow)
    | summarize TotalCount = count(), SuccessCount = countif(StatusCode == 200) by Operator, TimeBin = bin(TimeGenerated, lookbackWindow)
    | extend SuccessRate = todouble(SuccessCount) / TotalCount;
PerBin
| make-series AvgSuccessRate = avg(SuccessRate) default=0, AvgTotalCount = avg(TotalCount) default=0
    on TimeBin step lookbackWindow by Operator
| extend (Anomalies, Score, Baseline) = series_decompose_anomalies(AvgSuccessRate, zScoreThreshold)
| mv-expand TimeBin, AvgSuccessRate, AvgTotalCount, Anomalies, Score
| where todatetime(TimeBin) > ago(alertWindow)
| where toint(Anomalies) == 1
| where todouble(AvgSuccessRate) >= successRateGate and todouble(AvgTotalCount) >= minAttempts
| extend TriggerReason = strcat("인증프로세스_이상성공률스파이크_백도어의심_", Operator)
| extend Severity = "High"
| project TimeGenerated = todatetime(TimeBin), Operator, AvgSuccessRate = todouble(AvgSuccessRate), AvgTotalCount = todouble(AvgTotalCount), AnomalyScore = todouble(Score), TriggerReason, Severity
| order by TimeGenerated desc
